; VWF for the fixed labels of tilemaps (B-button menu, shops, ...). Kabuto.
;
; The labels used to be written into the tilemap with one fixed-width tile per letter.
; The cross bank table (wrappers.asm) now sends the tilemap decompress calls
; ($00, $01, $02 and $0F) through the routines below. They run the original routine and
; then look the tilemap up in StaticLabelTable (generated by scripts/set_static_labels.py
; into static_labels_table.asm). For every label of that tilemap the text is drawn with the
; menu VWF (patch/menu_vwf.asm) into the cells that the tilemap leaves blank.
;
; Table format: db group, index, label count, then per label
;   db row, column, width in cells ; dw string (VWF codes, $CB terminated)
; and a final db $FF. group/index are the a/e values of the decompress call, row/column are
; relative to the tilemap, the offset passed in bc is added like the game does.

INCLUDE "game/src/common/constants.asm"
INCLUDE "game/src/common/macros.asm"

DEF W_MenuVWFPendingPad   EQU $CCE4
DEF W_MenuVWFPendingWidth EQU $CCE5

DEF W_StaticLabelGroup EQU $CCE7
DEF W_StaticLabelIndex EQU $CCE8
DEF W_StaticLabelX     EQU $CCE9
DEF W_StaticLabelY     EQU $CCEB
DEF W_StaticLabelBase  EQU $CCEC
DEF W_StaticLabelCount EQU $CCED
DEF W_StaticLabelRecolour EQU $CCEA ; the width byte of the label being drawn, bit 7 = recolour, bit 6 = tab merge
DEF W_StaticLabelTabUpper EQU $CCEF
DEF W_StaticLabelTabLower EQU $CCF0
DEF M_StaticLabelTabTileTop EQU $14 ; blank tab tiles of the ability screen title (FIX in set_static_labels.py)
DEF M_StaticLabelTabTileBottom EQU $21
DEF W_MenuVWFBitmapCached EQU $CCF2 ; see menu_vwf.asm
DEF W_MenuVWFPoolBase EQU $CCF3 ; see menu_vwf.asm
DEF M_StaticLabelPopupPoolBase EQU $3E ; the pop-up menus draw into the pool tiles $3F-$7C
DEF M_MenuVWFBitmapCachedMagic EQU $A5

SECTION "Static Labels Bank 0 Functions", ROM0[$3E00]
StaticLabelsTilemapWTF::
  push af
  push bc
  push de
  call DecompressTilemapWTF
  ld a, $98
  jr StaticLabelsOverlay

StaticLabelsTilemap0Scroll::
  push af
  call GetOverworldScrollTileOffset
  pop af

StaticLabelsTilemap0::
  push af
  push bc
  push de
  call DecompressTilemap0
  ld a, $98
  jr StaticLabelsOverlay

StaticLabelsTilemap1::
  push af
  push bc
  push de
  call DecompressTilemap1
  ld a, $9C

StaticLabelsOverlay:
  ; a = high byte of the tilemap base. The stack holds the arguments of the original call.
  ld h, a
  pop de ; e = index
  pop bc ; bc = x, y offset
  pop af ; a = group
  ld l, a
  ld a, [W_CurrentBank]
  push af
  ld a, BANK(StaticLabelsRun)
  call VWFLowBankswitch
  call StaticLabelsRun
  pop af
  jp VWFLowBankswitch

SECTION "Static Labels Functions", ROMX[$6800], BANK[$C4]
StaticLabelsRun::
  ; l = group, e = index, b = x offset, c = y offset, h = high byte of the tilemap base
  ld a, l
  ld [W_StaticLabelGroup], a
  ld a, e
  ld [W_StaticLabelIndex], a
  ld a, b
  and $1F
  ld [W_StaticLabelX], a
  ld a, c
  and $1F
  ld [W_StaticLabelY], a
  ld a, h
  ld [W_StaticLabelBase], a
  ld hl, StaticLabelTable

.findScreen
  ld a, [hli]
  cp $FF
  ret z
  ld b, a ; group
  ld a, [hli]
  ld c, a ; index
  ld a, [hli]
  ld d, a ; label count
  ld a, [W_StaticLabelGroup]
  cp b
  jr nz, .skipScreen
  ld a, [W_StaticLabelIndex]
  cp c
  jr z, .found

.skipScreen
  ld a, d
  and $7F
  jr z, .findScreen
  ld d, a
  ld bc, 5 ; bytes per label

.skipLoop
  add hl, bc
  dec d
  jr nz, .skipLoop
  jr .findScreen

.found
  ; bit 7 of the count marks a tilemap that draws into the upper pool tiles ($3F-$7C): the pop-up menus (they cover
  ; labels and name plates of the screen under them, and when they close the game restores the tile ids but not
  ; the tile data) and the transformation panel (the lower pool is full). The scan then marks the upper tiles.
  ld a, d
  and $7F
  ret z
  ld [W_StaticLabelCount], a
  ld a, d
  rla ; carry = bit 7
  sbc a ; $FF for a pop-up, else 0
  and M_StaticLabelPopupPoolBase
  ld [W_MenuVWFPoolBase], a
  push hl ; the label table pointer
  call MenuVWFScanAll ; scan once, MenuVWFAllocate keeps the bitmap current for the labels
  pop hl
  ld a, M_MenuVWFBitmapCachedMagic
  ld [W_MenuVWFBitmapCached], a

.label
  ld a, [hli]
  ld b, a ; row
  ld a, [hli]
  ld c, a ; column
  ld a, [hli]
  ld [W_StaticLabelRecolour], a
  and $3F
  ld [W_MenuVWFPendingWidth], a
  ld a, [hli]
  ld e, a
  ld a, [hli]
  ld d, a ; de = string
  push hl ; next label
  push de

  ; hl = base + ((y + row) & $1F) * 32 + ((x + column) & $1F)
  ld a, [W_StaticLabelY]
  add b
  and $1F
  ld l, a
  ld h, 0
  add hl, hl
  add hl, hl
  add hl, hl
  add hl, hl
  add hl, hl
  ld a, [W_StaticLabelX]
  add c
  and $1F
  add l
  ld l, a ; the low byte of row * 32 is a multiple of 32, so this can't carry
  ld a, [W_StaticLabelBase]
  add h
  ld h, a

  pop bc ; string
  ld a, 1 ; left aligned, no padding
  ld [W_MenuVWFPendingPad], a
  push hl ; first cell
  call PutStringVWFCentered ; uses the field width set above for the number of cells
  pop hl
  ld a, [W_StaticLabelRecolour]
  ld b, a
  and $3F
  ld c, a
  bit 7, b
  call nz, StaticLabelRecolour
  bit 6, b
  call nz, StaticLabelTabMerge

.labelDone
  pop hl
  ld a, [W_StaticLabelCount]
  dec a
  ld [W_StaticLabelCount], a
  jr nz, .label
  xor a
  ld [W_MenuVWFPendingWidth], a
  ld [W_MenuVWFBitmapCached], a
  ld [W_MenuVWFPoolBase], a
  ret

StaticLabelRecolour::
  ; hl = first cell (tilemap, bank 0), c = number of cells. Swaps the colours of the glyph tiles the cells name
  ; (background 0 -> 1, ink 3 -> 2) by inverting bit plane 0, for labels on the black background of a palette
  ; that keeps its blue ink in colour 2. Preserves everything.
  push af
  push bc
  push de
  push hl

.cell
  call MenuVWFReadCell
  and a
  jr z, .next
  push hl
  ld l, a
  ld h, 0
  add hl, hl
  add hl, hl
  add hl, hl
  add hl, hl
  ld de, $9000
  add hl, de
  VRAMSwitchToBank1
  ld d, 8

.row
  di

.waitRow
  ldh a, [H_LCDStat]
  and 2
  jr nz, .waitRow
  ld a, [hl]
  cpl
  ld [hl+], a
  inc hl
  ei
  dec d
  jr nz, .row
  VRAMSwitchToBank0
  pop hl

.next
  inc hl
  dec c
  jr nz, .cell
  pop hl
  pop de
  pop bc
  pop af
  ret

StaticLabelTabMerge::
  ; hl = first cell of the lower row of a two row tab, c = number of cells. The same text was drawn into the
  ; row above (same columns). Moves the lower half of the upper glyph tile into the top of the lower tile
  ; and the upper half into the bottom of the upper tile, so the text is centred over the two rows, and
  ; fills the other halves with the border lines of the blank tab tiles. Preserves everything.
  push af
  push bc
  push de
  push hl

.cell
  call MenuVWFReadCell
  and a
  jr z, .next
  ld [W_StaticLabelTabLower], a
  push hl
  ld a, l
  sub 32
  ld l, a
  ld a, h
  sbc 0
  ld h, a
  call MenuVWFReadCell
  pop hl
  and a
  jr z, .next
  ld [W_StaticLabelTabUpper], a
  push hl
  push bc
  ; upper tile, bottom half = glyph lines 0-3 (taken from the lower tile before that one is changed)
  ld a, [W_StaticLabelTabLower]
  call .addr
  push hl
  ld a, [W_StaticLabelTabUpper]
  call .addr
  ld de, 8
  add hl, de
  ld d, h
  ld e, l
  pop hl
  ld c, 3
  call .copy
  ; upper tile, top half = the blank tab tile
  ld a, M_StaticLabelTabTileTop
  call .addr
  push hl
  ld a, [W_StaticLabelTabUpper]
  call .addr
  ld d, h
  ld e, l
  pop hl
  ld c, 2
  call .copy
  ; lower tile, top half = glyph lines 4-7
  ld a, [W_StaticLabelTabLower]
  call .addr
  ld d, h
  ld e, l
  ld bc, 8
  add hl, bc
  ld c, 3
  call .copy
  ; lower tile, bottom half = the blank tab tile
  ld a, M_StaticLabelTabTileBottom
  call .addr
  ld de, 8
  add hl, de
  push hl
  ld a, [W_StaticLabelTabLower]
  call .addr
  ld de, 8
  add hl, de
  ld d, h
  ld e, l
  pop hl
  ld c, 2
  call .copy
  pop bc
  pop hl

.next
  inc hl
  dec c
  jr nz, .cell
  pop hl
  pop de
  pop bc
  pop af
  ret

.addr
  ; hl = $9000 + a * 16
  ld l, a
  ld h, 0
  add hl, hl
  add hl, hl
  add hl, hl
  add hl, hl
  ld a, h
  add $90
  ld h, a
  ret

.copy
  ; Copies 8 bytes from hl to de. c bit 0 = VRAM bank of the source, bit 1 = bank of the destination.
  ld b, 8

.byte
  di
  ld a, c
  and 1
  ldh [H_RegVBK], a

.waitSrc
  ldh a, [H_LCDStat]
  and 2
  jr nz, .waitSrc
  ld a, [hl+]
  push af
  ld a, c
  srl a
  and 1
  ldh [H_RegVBK], a

.waitDst
  ldh a, [H_LCDStat]
  and 2
  jr nz, .waitDst
  pop af
  ld [de], a
  inc de
  ei
  dec b
  jr nz, .byte
  VRAMSwitchToBank0
  ret

SECTION "Static Labels Panel Redraw", ROM0[$3E90]
StaticLabelsPanelRedraw::
  ; Called from MedawatchPositionOverlayState instead of LCDCTileOverlaySetVisibility:
  ; repairs the panel, then shows the window layer as the original call did.
  call StaticLabelsPanelRepair
  jp LCDCTileOverlaySetVisibility

StaticLabelsRestoreHook::
  ; Replaces CrossBank $B3 (restore a saved rectangle of the background, a = slot, the
  ; original is bank 15:4F76). Runs the original, and after a restore of slot 3 repairs
  ; the pause menu panel while the screen is still black.
  ;
  ; On the Medawatch screen the panel is not the window layer (that one shows the portrait
  ; at the bottom right). It is part of the background map, columns 12-19, and the game
  ; brings it back from a saved copy of the background whenever a Medarot screen opened
  ; from the Medawatch menu is left. The copy holds the tile ids of the labels but not the
  ; tile data: the Medarot screen has drawn its own VWF text into the same pool tiles
  ; meanwhile, so the labels came back as pieces of that text.
  push af
  push hl
  ld b, a ; b = slot
  ld a, [W_CurrentBank]
  ld c, a ; c = bank of the caller
  push bc
  ld a, $15
  call VWFLowBankswitch
  pop bc
  push bc
  ld a, b
  call $4F76
  pop bc
  push bc
  ld a, c
  call VWFLowBankswitch
  pop bc
  ld a, b
  cp 3
  call z, StaticLabelsPanelRepair
  pop hl
  pop af
  ret

StaticLabelsPanelRepair::
  ; Redraws the labels of the pause menu panel (tilemap 00:12, background column 12, row 0)
  ; into the tiles its cells already name. Does nothing when the panel frame isn't there.
  ; Preserves everything.
  push af
  push bc
  push de
  push hl
  ld hl, $9800 + 12
  call .readCell
  cp $D4 ; top left corner of the panel frame
  jr nz, .done
  ld hl, $9800 + 12 + 32
  call .readCell
  cp $DB ; its left edge
  jr nz, .done
  ld a, [W_CurrentBank]
  push af
  ld a, BANK(StaticLabelsRun)
  call VWFLowBankswitch
  ld l, $00 ; group
  ld e, $12 ; index
  ld bc, $0C00 ; the panel sits at column 12, row 0
  ld h, $98
  call StaticLabelsRun
  pop af
  call VWFLowBankswitch

.done
  pop hl
  pop de
  pop bc
  pop af
  ret

.readCell
  di

.waitVRAM
  ldh a, [H_LCDStat]
  and 2
  jr nz, .waitVRAM
  ld a, [hl]
  ei
  ret
